#include "libzippp.h"
#include <zip.h>
#include <cassert>
#include <iostream>
#include <sstream>
#include <string>

using namespace std;
using namespace libzippp;

static void addRawEntry(zip_t* zh, const string& name, const char* content) {
    if (!name.empty() && name[name.size()-1]=='/') {
        assert(zip_dir_add(zh, name.c_str(), 0) >= 0);
    } else {
        zip_source_t* source = zip_source_buffer(zh, content, strlen(content), 0);
        assert(source != nullptr);
        assert(zip_file_add(zh, name.c_str(), source, 0) >= 0);
    }
}

static void buildInitial() {
    int err = 0;
    zip_t* zh = zip_open("/tmp/scen/s.zip", ZIP_CREATE|ZIP_TRUNCATE, &err);
    assert(zh);
    addRawEntry(zh, "a/", "");
    addRawEntry(zh, "a/f.txt", "F");
    addRawEntry(zh, "g.txt", "G");
    addRawEntry(zh, "a-sibling/x.txt", "X");
    assert(zip_close(zh)==0);
}

int main() {
    buildInitial();

    ZipArchive z("/tmp/scen/s.zip");
    assert(z.open(ZipArchive::Write));

    //save objects for a/ and a/f.txt
    ZipEntry dir = z.getEntry("a/");
    ZipEntry file = z.getEntry("a/f.txt");
    ZipEntry g = z.getEntry("g.txt");
    assert(!dir.isNull() && !file.isNull() && !g.isNull());

    //content reads follow the entry
    assert(file.readAsText()=="F");

    //move a/ to b/ using the saved directory object
    assert(z.renameEntry(dir, "b/")==2);
    assert(z.hasEntry("b/") && z.hasEntry("b/f.txt"));
    assert(!z.hasEntry("a/") && !z.hasEntry("a/f.txt"));
    //stale object name, but content read follows the slot
    assert(file.getName()=="a/f.txt");
    assert(file.readAsText()=="F");

    //create another a/ with files
    assert(z.addData("a/f.txt", "NEWA", 4));
    assert(z.addData("a/h.txt", "H", 1));
    assert(z.hasEntry("a/") && z.hasEntry("a/f.txt") && z.hasEntry("a/h.txt"));
    assert(z.getEntry("a/f.txt").readAsText()=="NEWA");

    //rename saved dir object b/ -> c/ : moves b/'s current contents, new a/ untouched
    assert(z.renameEntry(dir, "c/")==2);
    assert(z.hasEntry("c/") && z.hasEntry("c/f.txt"));
    assert(!z.hasEntry("b/"));
    assert(z.hasEntry("a/") && z.hasEntry("a/f.txt") && z.hasEntry("a/h.txt"));
    assert(z.getEntry("a/f.txt").readAsText()=="NEWA");
    assert(file.readAsText()=="F"); //the saved file object now points at c/f.txt

    //the saved file object can be renamed on its own
    assert(z.renameEntry(file, "c/f2.txt")==1);
    assert(z.hasEntry("c/f2.txt") && !z.hasEntry("c/f.txt"));
    assert(file.readAsText()=="F");

    //rename to its own current name -> INVALID_PARAMETER
    assert(z.renameEntry(file, "c/f2.txt")==LIBZIPPP_ERROR_INVALID_PARAMETER);
    //... while by-name of the stale name hits the *new* a/f.txt: rename a/f.txt->a/f3.txt?
    //  by-name resolves new entry; rename to same name invalid
    assert(z.renameEntry("a/f.txt", "a/f.txt")==LIBZIPPP_ERROR_INVALID_PARAMETER);

    //a copy of the saved object shares the identity
    ZipEntry fileCopy = file;
    assert(z.renameEntry(fileCopy, "c/f3.txt")==1);
    assert(z.hasEntry("c/f3.txt"));
    assert(file.readAsText()=="F");

    //delete the saved file object: only c/f3.txt goes
    assert(z.deleteEntry(file)==1);
    assert(!z.hasEntry("c/f3.txt"));
    //object now invalid, even though old name "a/f.txt" exists (new entry)
    assert(z.deleteEntry(file)==LIBZIPPP_ERROR_INVALID_ENTRY);
    assert(z.renameEntry(file, "x.txt")==LIBZIPPP_ERROR_INVALID_ENTRY);
    //new a/ entries still intact
    assert(z.hasEntry("a/f.txt") && z.getEntry("a/f.txt").readAsText()=="NEWA");
    assert(z.hasEntry("a/h.txt"));

    //add a child under c/ after the move; delete saved dir object -> removes c/ + current children only
    assert(z.addData("c/late.txt", "L", 1));
    assert(z.deleteEntry(dir)==2); //c/ and c/late.txt (c/f3.txt already gone)
    assert(!z.hasEntry("c/") && !z.hasEntry("c/late.txt"));
    //similar neighbor untouched
    assert(z.hasEntry("a-sibling/") && z.hasEntry("a-sibling/x.txt"));

    //dir object now invalid (deleted); reuse name c/ by a new entry -> still INVALID_ENTRY
    assert(z.addData("c/new.txt", "CN", 2));
    assert(z.deleteEntry(dir)==LIBZIPPP_ERROR_INVALID_ENTRY);
    assert(z.renameEntry(dir, "d/")==LIBZIPPP_ERROR_INVALID_ENTRY);
    assert(z.hasEntry("c/new.txt"));

    //plain file old-name reuse: g.txt moved, new g.txt created, saved object tracks the old one
    assert(z.renameEntry(g, "g1.txt")==1);
    assert(z.addData("g.txt", "NEWG", 4));
    assert(z.getEntry("g.txt").readAsText()=="NEWG");
    assert(z.deleteEntry(g)==1); //deletes g1.txt
    assert(!z.hasEntry("g1.txt"));
    assert(z.hasEntry("g.txt") && z.getEntry("g.txt").readAsText()=="NEWG");

    //pending modifications preserved across an INVALID_ENTRY return
    assert(z.getEntry("a/h.txt").getComment().empty());

    assert(z.close()==LIBZIPPP_OK);

    //reopen and verify final state
    ZipArchive r("/tmp/scen/s.zip");
    assert(r.open(ZipArchive::ReadOnly));
    assert(r.hasEntry("a/") && r.hasEntry("a/f.txt") && r.hasEntry("a/h.txt"));
    assert(r.getEntry("a/f.txt").readAsText()=="NEWA");
    assert(r.getEntry("a/h.txt").readAsText()=="H");
    assert(r.hasEntry("c/new.txt") && r.getEntry("c/new.txt").readAsText()=="CN");
    assert(r.hasEntry("g.txt") && r.getEntry("g.txt").readAsText()=="NEWG");
    assert(!r.hasEntry("b/") && !r.hasEntry("c/") && !r.hasEntry("g1.txt"));
    assert(r.hasEntry("a-sibling/x.txt"));
    r.close();

    cout << "scenario 1 OK\n";
    return 0;
}
